WITH kept_keys AS (SELECT job_title FROM employees INTERSECT ALL SELECT job_title FROM employees WHERE manager_id = 23), reconciled AS (SELECT s.* FROM employees s INNER JOIN kept_keys k ON s.job_title = k.job_title) SELECT DATE_TRUNC('QUARTER', hire_date) AS quarter_start, COUNT(DISTINCT manager_id) AS distinct_manager_ids, COUNT(*) AS cnt, COUNT(*) AS num_rows FROM reconciled GROUP BY DATE_TRUNC('QUARTER', hire_date)
